import React from 'react';

import { TooltipItem } from '../../../types/tooltip.js';
import { TooltipActionTemplate } from '../../tooltip/shared/hooks/useTooltipSeriesActions.js';

export const getCustomActionItems = (
  actions?: TooltipActionTemplate,
  item?: TooltipItem,
): React.JSX.Element[] => {
  if (!actions) {
    return [];
  }

  const actionItems = item
    ? actions(item)?.props.children
    : actions()?.props.children;

  return React.Children.toArray(actionItems) as React.JSX.Element[];
};
